class Animal:
    def move(self): return 'moving'
class Bird(Animal):
    def fly(self): return 'flying'
b = Bird()
print(b.move(), b.fly())

class Animal:
    def sound(self): return 'sound'
class Cat(Animal):
    def sound(self): return 'meow'
print(Cat().sound())

class Base:
    def label(self): return 'base'
class Child(Base):
    def label(self): return super().label() + '-child'
print(Child().label())

class Person:
    def __init__(self, name): self.name = name
class Student(Person):
    def __init__(self, name, level):
        super().__init__(name); self.level = level
s = Student('Ira', 2)
print(s.name, s.level)
